window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5e1d8bbcfccafdfb"]={"versions": [{"id": "FIG-5e1d8bbcfccafdfb", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsdiagramm (ECUC-Metamodell / UML-Klassendiagramm) kombiniert mit einer tabellarischen Konfigurationsklassen-Übersicht. Die Darstellung spezifiziert die Konfigurationsstruktur des Diagnostic Event Managers (Dem) im AUTOSAR-Classic-Platform-BSW-Kontext für Benachrichtigungen bei Änderungen des Event- und Monitor-Status.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DemEventParameter</code>: Container-Definition (<code>EcucParamConfContainerDef</code>), Multiplizität 1..65535, fungiert als Eltern-Container.</li>\n<li><code>DemCallbackEventUdsStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, assoziiert über Kompositionsbeziehung <code>+subContainer</code>, markiert mit Hinweis <code>A</code>.</li>\n<li><code>DemCallbackEventUdsStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>), Multiplizität 0..1, zugeordnet über Kompositionsbeziehung <code>+parameter</code>.</li>\n<li><code>DemCallbackMonitorStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, assoziiert über Kompositionsbeziehung <code>+subContainer</code>, markiert mit Hinweis <code>A</code>.</li>\n<li><code>DemCallbackMonitorStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>), Multiplizität 0..1, zugeordnet über Kompositionsbeziehung <code>+parameter</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Konfigurationsmetamodell-Struktur. Zur Laufzeit triggert der Dem bei Änderung des UDS- oder Monitor-Status eines konfigurierten Diagnose-Events die über <code>DemCallbackEventUdsStatusChangedFnc</code> bzw. <code>DemCallbackMonitorStatusChangedFnc</code> referenzierten Callback-Funktionen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konfigurationsklassen: <code>Pre-compile time</code> (X, All Variants), <code>Link time</code> (–), <code>Post-build time</code> (–) für Multiplizität und Wert.</li>\n<li>Gültigkeitsbereich (<code>Scope / Dependency</code>): ECU.</li>\n<li>Keine untergeordneten Container (<code>No Included Containers</code>).</li>\n<li>Kardinalitäten: Mindestens ein <code>DemEventParameter</code> erforderlich (bis zu 65535). Callback-Container sind optional und mehrfach instanziierbar (0..*), die Funktionsnamen jeweils optional (0..1).</li>\n</ul>"}, {"id": "FIG-c81202b9d15d8111", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsspezifikation (ECUC-Metamodell) bestehend aus tabellarischer Parameterbeschreibung, Konfigurationsklassen-Tabelle und UML-Klassendiagramm für die Konfiguration von Event-Status-Benachrichtigungen im Diagnostic Event Manager (Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DemEventParameter</code>: Container-Definition (<code>EcucParamConfContainerDef</code>), Multiplizität 1..65535, übergeordneter Container.</li>\n<li><code>DemCallbackEventUdsStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, Assoziation <code>+subContainer</code>, markiert mit Kennzeichnung <code>A</code>.</li>\n<li><code>DemCallbackEventUdsStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>), Multiplizität 0..1, Assoziation <code>+parameter</code>.</li>\n<li><code>DemCallbackMonitorStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, Assoziation <code>+subContainer</code>, markiert mit Kennzeichnung <code>A</code>.</li>\n<li><code>DemCallbackMonitorStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>, SWS Item <code>[ECUC_Dem_00937]</code>), Multiplizität 0..1, Assoziation <code>+parameter</code> unter Eltern-Container <code>DemCallbackMonitorStatusChanged</code>. Definiert den C-Funktionsnamen gemäß Prototyp <code>&lt;Module&gt;_DemTriggerOnMonitorStatus</code>. Falls nicht konfiguriert, fordert der Dem einen RTE-R-Port mit dem Interface <code>CallbackMonitorStatusChanged</code> an (gebildet aus Callback-Präfix und Event-Name).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Konfigurationsmetamodell-Struktur. Zur Laufzeit triggert der Dem bei Änderung des UDS- oder Monitor-Status eines konfigurierten Diagnose-Events die über <code>DemCallbackEventUdsStatusChangedFnc</code> bzw. <code>DemCallbackMonitorStatusChangedFnc</code> referenzierten Callback-Funktionen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>SWS-Element: <code>[ECUC_Dem_00937]</code> für <code>DemCallbackMonitorStatusChangedFnc</code>.</li>\n<li>Konfigurationsklasse: Pre-compile time für alle Varianten (<code>X</code>), keine Unterstützung für Link time oder Post-build time (<code>–</code>).</li>\n<li>Post-Build-Varianz: <code>Post-Build Variant Multiplicity = false</code>, <code>Post-Build Variant Value = false</code>.</li>\n<li>Gültigkeitsbereich (<code>Scope / Dependency</code>): ECU.</li>\n<li>Keine untergeordneten Container innerhalb von <code>DemCallbackMonitorStatusChanged</code> (<code>No Included Containers</code>).</li>\n</ul>"}, {"id": "FIG-a567b1ccc61c9ca1", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsspezifikation (ECUC-Metamodell) bestehend aus tabellarischer Parameterbeschreibung, Konfigurationsklassen-Tabelle und UML-Klassendiagramm für die Konfiguration von Event-Status-Benachrichtigungen im Diagnostic Event Manager (Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DemEventParameter</code>: Container-Definition (<code>EcucParamConfContainerDef</code>), Multiplizität 1..65535, übergeordneter Container.</li>\n<li><code>DemCallbackEventUdsStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, Assoziation <code>+subContainer</code>, markiert mit Kennzeichnung <code>A</code>.</li>\n<li><code>DemCallbackEventUdsStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>), Multiplizität 0..1, Assoziation <code>+parameter</code>.</li>\n<li><code>DemCallbackMonitorStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, Assoziation <code>+subContainer</code>, markiert mit Kennzeichnung <code>A</code>.</li>\n<li><code>DemCallbackMonitorStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>, SWS Item <code>[ECUC_Dem_00937]</code>), Multiplizität 0..1, Assoziation <code>+parameter</code> unter Eltern-Container <code>DemCallbackMonitorStatusChanged</code>. Definiert den C-Funktionsnamen gemäß Prototyp <code>&lt;Module&gt;_DemTriggerOnMonitorStatus</code>. Falls nicht konfiguriert, fordert der Dem einen RTE-R-Port mit dem Interface <code>CallbackMonitorStatusChanged</code> an (gebildet aus Callback-Präfix und Event-Name).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Konfigurationsmetamodell-Struktur. Zur Laufzeit triggert der Dem bei Änderung des UDS- oder Monitor-Status eines konfigurierten Diagnose-Events die über <code>DemCallbackEventUdsStatusChangedFnc</code> bzw. <code>DemCallbackMonitorStatusChangedFnc</code> referenzierten Callback-Funktionen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>SWS-Element: <code>[ECUC_Dem_00937]</code> für <code>DemCallbackMonitorStatusChangedFnc</code>.</li>\n<li>Konfigurationsklasse: Pre-compile time für alle Varianten (<code>X</code>), keine Unterstützung für Link time oder Post-build time (<code>–</code>).</li>\n<li>Post-Build-Varianz: <code>Post-Build Variant Multiplicity = false</code>, <code>Post-Build Variant Value = false</code>.</li>\n<li>Gültigkeitsbereich (<code>Scope / Dependency</code>): ECU.</li>\n<li>Keine untergeordneten Container innerhalb von <code>DemCallbackMonitorStatusChanged</code> (<code>No Included Containers</code>).</li>\n</ul>"}, {"id": "FIG-c2fb3015ccb68b7e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsdiagramm (ECUC-Metamodell / UML-Klassendiagramm) zur Spezifikation der Event-Status-Benachrichtigungskonfiguration im Diagnostic Event Manager (Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DemEventParameter</code>: Container-Definition (<code>EcucParamConfContainerDef</code>), Multiplizität 1..65535, fungiert als übergeordneter Container.</li>\n<li><code>DemCallbackEventUdsStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, assoziiert über <code>+subContainer</code>, mit Dokumentensymbol referenziert.</li>\n<li><code>DemCallbackEventUdsStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>), Multiplizität 0..1, assoziiert über <code>+parameter</code>.</li>\n<li><code>DemCallbackMonitorStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, assoziiert über <code>+subContainer</code>, mit Dokumentensymbol referenziert.</li>\n<li><code>DemCallbackMonitorStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>), Multiplizität 0..1, assoziiert über <code>+parameter</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Konfigurationsmetamodell-Struktur. Zur Laufzeit triggert der Dem bei Änderung des UDS- oder Monitor-Status eines konfigurierten Diagnose-Events die über <code>DemCallbackEventUdsStatusChangedFnc</code> bzw. <code>DemCallbackMonitorStatusChangedFnc</code> referenzierten Callback-Funktionen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Metamodell-Kardinalitäten: <code>DemEventParameter</code> 1..65535; Sub-Container <code>DemCallbackEventUdsStatusChanged</code> und <code>DemCallbackMonitorStatusChanged</code> jeweils 0..*; Funktionsparameter jeweils 0..1.</li>\n<li>Beide Sub-Container verweisen über das Dokumentensymbol auf eine ausgelagerte detaillierte Containerspezifikation.</li>\n</ul>"}, {"id": "FIG-f66c64de1785e879", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECU-Konfigurationsdiagramm (ECUC-Metamodell / UML-Klassendiagramm) zur Spezifikation der Event-Status-Benachrichtigungskonfiguration im Diagnostic Event Manager (Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DemEventParameter</code>: Container-Definition (<code>EcucParamConfContainerDef</code>), Multiplizität 1..65535, fungiert als übergeordneter Container.</li>\n<li><code>DemCallbackEventUdsStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, assoziiert über <code>+subContainer</code>, mit Dokumentensymbol referenziert.</li>\n<li><code>DemCallbackEventUdsStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>), Multiplizität 0..1, assoziiert über <code>+parameter</code>.</li>\n<li><code>DemCallbackMonitorStatusChanged</code>: Sub-Container (<code>EcucParamConfContainerDef</code>), Multiplizität 0..*, assoziiert über <code>+subContainer</code>, mit Dokumentensymbol referenziert.</li>\n<li><code>DemCallbackMonitorStatusChangedFnc</code>: Parameter (<code>EcucFunctionNameDef</code>), Multiplizität 0..1, assoziiert über <code>+parameter</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Konfigurationsmetamodell-Struktur. Zur Laufzeit triggert der Dem bei Änderung des UDS- oder Monitor-Status eines konfigurierten Diagnose-Events die über <code>DemCallbackEventUdsStatusChangedFnc</code> bzw. <code>DemCallbackMonitorStatusChangedFnc</code> referenzierten Callback-Funktionen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Metamodell-Kardinalitäten: <code>DemEventParameter</code> 1..65535; Sub-Container <code>DemCallbackEventUdsStatusChanged</code> und <code>DemCallbackMonitorStatusChanged</code> jeweils 0..*; Funktionsparameter jeweils 0..1.</li>\n<li>Beide Sub-Container verweisen über das Dokumentensymbol auf eine ausgelagerte detaillierte Containerspezifikation.</li>\n</ul>"}], "trans": [{"from": "FIG-5e1d8bbcfccafdfb", "to": "FIG-c81202b9d15d8111", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung der tabellarischen Parameter-Spezifikation für <code>DemCallbackMonitorStatusChangedFnc</code> ([ECUC_Dem_00937]) inklusive <code>Parent Container</code>, <code>Multiplicity</code> (0..1), <code>Type</code> (<code>EcucFunctionNameDef</code>), <code>Post-Build Variant Multiplicity</code> (false), <code>Post-Build Variant Value</code> (false) und <code>Scope / Dependency</code> (ECU).</li>\n<li>Ergänzung des einleitenden Beschreibungstextes zu <code>DemCallbackMonitorStatusChanged</code> sowie der textuellen Definition des C-Funktionsprototyps bzw. des alternativen RTE-R-Ports (<code>CallbackMonitorStatusChanged</code>).</li>\n<li>Wegfall der oberen Konfigurationstabelle ohne Kopfzeile/Parameterzuordnung.</li>\n</ul>"}, {"from": "FIG-c81202b9d15d8111", "to": "FIG-a567b1ccc61c9ca1", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a567b1ccc61c9ca1", "to": "FIG-c2fb3015ccb68b7e", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Wegfall des oberen Beschreibungsblocks und der tabellarischen Parameterdefinition für <code>DemCallbackMonitorStatusChangedFnc</code> ([ECUC_Dem_00937]).</li>\n<li>Wegfall der Trennleiste <code>No Included Containers</code>.</li>\n<li>Ersetzung des roten Hinweises <code>A</code> an <code>DemCallbackEventUdsStatusChanged</code> und <code>DemCallbackMonitorStatusChanged</code> durch ein blaues Dokumentensymbol.</li>\n</ul>"}, {"from": "FIG-c2fb3015ccb68b7e", "to": "FIG-f66c64de1785e879", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
